/* Cache only the public app shell, never sign-in routes, user data, or third-party responses. */
const CACHE='flow-shell-22205e1801c9';
const ASSETS=["./app.22205e1801c9.js","./core.22205e1801c9.js","./icons/apple-touch-icon.png","./icons/icon-192.png","./icons/icon-512.png","./icons/icon.svg","./icons/maskable-512.png","./index.html","./manifest.webmanifest","./sample.22205e1801c9.js","./storage.22205e1801c9.js","./styles.22205e1801c9.css"];
const ROOT=new URL('./',self.location.href);
const URLS=ASSETS.map(p=>new URL(p,ROOT).href);
async function valid(response,url){if(!response.ok||response.redirected||response.type==='opaque')return false;if(url.endsWith('/index.html'))return (await response.clone().text()).includes('name="flow-app" content="1"');if(url.endsWith('.js'))return /javascript/.test(response.headers.get('content-type')||'');if(url.endsWith('.css'))return /text\/css/.test(response.headers.get('content-type')||'');if(url.endsWith('.png'))return /image\/png/.test(response.headers.get('content-type')||'');if(url.endsWith('.svg'))return /image\/svg/.test(response.headers.get('content-type')||'');if(url.endsWith('.webmanifest')){try{return (await response.clone().json()).short_name==='Flow';}catch{return false;}}return true;}
self.addEventListener('install',event=>event.waitUntil((async()=>{try{const fetched=await Promise.all(URLS.map(async url=>{const response=await fetch(new Request(url,{cache:'reload',credentials:'same-origin'}));if(!await valid(response,url))throw Error('Cannot cache '+new URL(url).pathname+' (HTTP '+response.status+', '+(response.headers.get('content-type')||'no content type')+(response.redirected?', redirected':'')+').');return [url,response];}));const cache=await caches.open(CACHE);await Promise.all(fetched.map(([url,response])=>cache.put(url,response)));}catch(error){for(const client of await self.clients.matchAll({includeUncontrolled:true,type:'window'}))client.postMessage({type:'OFFLINE_ERROR',message:error.message});throw error;}})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{const previous=(await caches.keys()).filter(k=>k.startsWith('flow-shell-')&&k!==CACHE);await Promise.all(previous.slice(0,-1).map(k=>caches.delete(k)));await self.clients.claim();})()));
self.addEventListener('message',event=>{if(event.data?.type==='ACTIVATE')self.skipWaiting();if(event.data?.type==='OFFLINE_STATUS')event.waitUntil((async()=>{const cache=await caches.open(CACHE);const found=await Promise.all(URLS.map(u=>cache.match(u)));event.ports[0]?.postMessage({ready:found.every(Boolean)});})());});
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==ROOT.origin)return;
 const isHome=url.pathname===ROOT.pathname||url.pathname===ROOT.pathname+'index.html';
 if(event.request.mode==='navigate'&&isHome){event.respondWith((async()=>{try{return await fetch(event.request);}catch{return await caches.open(CACHE).then(c=>c.match(new URL('index.html',ROOT).href))||new Response('Open Flow once while online to prepare offline reading.',{status:503,headers:{'Content-Type':'text/plain'}});}})());return;}
 if(URLS.includes(url.href)){event.respondWith((async()=>{const cache=await caches.open(CACHE);return await cache.match(url.href)||fetch(event.request);})());}
});
